# Test-support stub: prices.internal is not resolvable from this sandbox,
# so serve the documented price API locally for the tests only.
import json
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer

PRICES = {"A100": 12.5, "B200": 17.5}

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        sku = self.path.rsplit("/", 1)[-1]
        if sku in PRICES:
            body = json.dumps({"price": PRICES[sku]}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()
    def log_message(self, *a): pass

def _start_server():
    srv = HTTPServer(("127.0.0.1", 0), Handler)
    port = srv.server_address[1]
    t = threading.Thread(target=srv.serve_forever, daemon=True)
    t.start()
    return srv, port

_server = None

def _patch_getaddrinfo():
    real = __import__("socket").getaddrinfo
    def fake(host, *args, **kw):
        if host == "prices.internal":
            return real("127.0.0.1", *args, **kw)
        return real(host, *args, **kw)
    __import__("socket").getaddrinfo = fake

def pytest_configure(config):
    global _server
    _server, port = _start_server()
    import prices, socket
    real = socket.getaddrinfo
    def fake(host, port_=None, *a, **kw):
        if host == "prices.internal":
            return real("127.0.0.1", port_, *a, **kw)
        return real(host, port_, *a, **kw)
    socket.getaddrinfo = fake
    prices.BASE = f"http://127.0.0.1:{port}/api/v1/price"
EOF
pytest -q 2>&1 | tail -5"}
